INSERT INTO public.cadets (
  profile_id, rotc_unit, serial_number, company, platoon, rank,
  emergency_contact_name, emergency_contact_relationship, emergency_contact_phone
)
SELECT
  p.id,
  '604th (ILO) CDC, ISUFST ROTC Unit',
  'SN-2026-' || LPAD((ROW_NUMBER() OVER (ORDER BY p.student_id))::text, 4, '0'),
  p.company,
  p.platoon,
  p.rank,
  p.emergency_contact_name,
  'Parent/Guardian',
  p.emergency_contact_phone
FROM inserted_profiles p;

-- 5. VERIFY COUNTS
SELECT 
  company, 
  platoon, 
  COUNT(*) as cadets_count 
FROM public.profiles 
WHERE role = 'cadet' AND status = 'approved'
GROUP BY company, platoon
ORDER BY company, platoon;
